<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <algorithm>
#include <iostream>
#include <vector>
#include <queue>
using namespace std;
vector<int> adj[2020];
int ir[20][20], sc[20][20], pc[20][20];
char s[20][20], p[20][20];
int dd[20][20];
int dx[4]={0,1,-1,0};
int dy[4]={1,0,0,-1};
vector<int> ns[20][20], np[20][20];

void add_edge(int a, int b) {
    adj[a].push_back(b);
    adj[b].push_back(a);
}

int dist[2020], parent[2020], sp, pp;

bool bfs() {
    queue<int> q;
    for (int i=1; i<=sp; i++) {
        if (parent[i]==0) {
            dist[i]=0;
            q.push(i);
        } else {
            dist[i]=3010;
        }
    }
    dist[0]=3010;
    while (!q.empty()) {
        int u=q.front(); q.pop();
        if (dist[u]<dist[0]) {
            for (int v_idx=0; v_idx<(int)adj[u].size(); v_idx++) {
                int v=parent[adj[u][v_idx]];
                if (dist[v]>dist[u]+1) {
                    dist[v]=dist[u]+1;
                    q.push(v);
                }
            }
        }
    }
    return dist[0]!=3010;
}

bool dfs(int x) {
    if (x==0) return true;
    for (int i=0; i<(int)adj[x].size(); i++) {
        int u=parent[adj[x][i]];
        if (dist[u]==dist[x]+1) {
            if (dfs(u)) {
                parent[x]=adj[x][i];
                parent[adj[x][i]]=x;
                return true;
            }
        }
    }
    return false;
}

int max_match() {
    int match_count=0;
    while (bfs()) {
        for (int i=1; i<=sp; i++) {
            if (parent[i]==0)
                match_count+=dfs(i);
        }
    }
    return match_count;
}

int n,t;
void process(int a,int b) {
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=n; j++) {
            dd[i][j]=100000;
        }
    }
    queue<pair<int,int>> q;
    dd[a][b]=0;
    q.push({a,b});
    while (!q.empty()) {
        auto [x,y]=q.front(); q.pop();
        for (int i=0; i<(int)np[x][y].size(); i++)
            for (int j=0; j<(int)ns[a][b].size(); j++)
                add_edge(ns[a][b][j], np[x][y][i]);
        if (dd[x][y]==ir[x][y]) continue;
        for (int d=0; d<4; d++) {
            int nx=x+dx[d], ny=y+dy[d];
            if (sc[nx][ny]!=-1 && dd[nx][ny]>dd[x][y]+1 && dd[x][y]+1<=ir[nx][ny]) {
                dd[nx][ny]=dd[x][y]+1;
                q.push({nx,ny});
            }
        }
    }
}

int main() {
    cin >> n >> t;
    for (int i=1; i<=n; i++)
        for (int j=1; j<=n; j++)
            ir[i][j]=t;
    for (int i=1; i<=n; i++)
        cin >> s[i]+1;
    for (int i=1; i<=n; i++)
        cin >> p[i]+1;
    int rx, ry;
    sp=1; pp=1000;
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=n; j++) {
            if (s[i][j]=='Z'||s[i][j]=='Y') {
                sc[i][j]=-1; ir[i][j]=0;
            }
            if (s[i][j]=='Z') {
                rx=i; ry=j; ir[i][j]=0;
            }
            if ('0'<=s[i][j] && s[i][j]<='9') {
                sc[i][j]=s[i][j]-'0';
            }
            for (int k=0; k<sc[i][j]; k++)
                ns[i][j].push_back(sp++);
        }
    }
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=n; j++) {
            if ('0'<=p[i][j] && p[i][j]<='9') {
                pc[i][j]=p[i][j]-'0';
            }
            for (int k=0; k<pc[i][j]; k++)
                np[i][j].push_back(pp++);
        }
    }
    queue<pair<int,int>> q;
    q.push({rx,ry});
    while (!q.empty()) {
        auto [x,y]=q.front(); q.pop();
        for (int d=0; d<4; d++) {
            int nx=x+dx[d], ny=y+dy[d];
            if (ir[nx][ny]>ir[x][y]+1 && sc[nx][ny]!=-1) {
                ir[nx][ny]=ir[x][y]+1;
                q.push({nx,ny});
            }
        }
    }
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=n; j++) {
            if (sc[i][j]>0) {
                process(i,j);
            }
        }
    }
    cout << max_match() << endl;
}
